/**
 * Delegate runs as the band and the records pane see them: which Bash call is a `delegate.py run`,
 * what its output and its background task's notification say, and the run folders `delegate.py list`
 * reports. Kept free of `$` so tests can read it. The brief (the heredoc) is never read.
 */
import type { DelegateRecord, DelegateRun, DelegateTool, DelegateUsage } from '../types'
import { TOOL_NAME } from './delegate'
import type { Messages } from './i18n'

/** delegate.py's own default --timeout, in minutes. */
export const DEFAULT_TIMEOUT_MIN = 30

const TOOLS: readonly DelegateTool[] = ['codex', 'agent', 'agy']

/** The shell words of one line, quotes undone, up to a heredoc, a pipe, a redirect or a separator. */
const words = (text: string): string[] => {
  const out: string[] = []
  let word = ''
  let quote = ''
  let isWord = false
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i]!
    if (quote) {
      if (c === quote) quote = ''
      else if (c === '\\' && quote === '"' && i + 1 < text.length) word += text[++i]
      else word += c
      continue
    }
    if (c === "'" || c === '"') {
      quote = c
      isWord = true
    } else if (c === '\\' && i + 1 < text.length) {
      word += text[++i]
      isWord = true
    } else if (/\s/.test(c)) {
      if (isWord) out.push(word)
      word = ''
      isWord = false
    } else if (';&|<>'.includes(c)) {
      if (isWord) out.push(word)
      return out
    } else {
      word += c
      isWord = true
    }
  }
  if (isWord) out.push(word)
  return out
}

export type DelegateCall = { label: string; tool?: DelegateTool; name?: string; timeoutMin: number }

/**
 * The flags of the first `delegate.py run` in a Bash command, or null when there is none (a dry run
 * runs nothing, so it is none). Only the command line up to the heredoc is read, never the brief.
 */
export const parseDelegateCall = (command: string): DelegateCall | null => {
  const found = command.match(/delegate\.py['"]?[ \t]+run(?=[\s;&|<]|$)/)
  if (!found) return null
  const rest = command.slice(found.index! + found[0].length).replace(/\\\r?\n/g, ' ').split('\n')[0]!
  const flags = words(rest)
  if (flags.includes('--dry-run')) return null
  const flag = (name: string) => {
    for (let i = 0; i < flags.length; i += 1) {
      if (flags[i] === name) return flags[i + 1]
      if (flags[i]!.startsWith(`${name}=`)) return flags[i]!.slice(name.length + 1)
    }
    return undefined
  }
  const tool = TOOLS.find(t => t === flag('--tool'))
  const label = (flag('--label') ?? tool ?? 'delegate').slice(0, 12)
  const name = flag('--name')?.trim().slice(0, 40) || flag('--model')?.slice(0, 40) || undefined
  const timeout = Number(flag('--timeout'))
  return { label, tool, name, timeoutMin: Number.isFinite(timeout) && timeout > 0 ? timeout : DEFAULT_TIMEOUT_MIN }
}

/** A run folder's answer file, in any of the languages delegate.py prints. */
const ANSWER_PATH = /(\/\S*?\/\d{8}-\d{6}-[A-Za-z0-9]{1,6}-[0-9a-f]{4}\/answer\.md)/

/**
 * What a `delegate.py run`'s output says: the seconds on its `[delegate] … · N s · outcome` line (the
 * unit is the language's: s, 秒, 초) and the answer file's path.
 */
export const parseDelegateOutput = (text: string): { seconds?: number; answerPath?: string } => {
  const header = text.split('\n').find(line => line.startsWith('[delegate] ')) ?? ''
  const seconds = header.match(/·\s*(\d+(?:\.\d+)?)\s*(?:s|秒|초)\s*·/)
  const path = text.match(ANSWER_PATH)
  return {
    ...(seconds ? { seconds: Number(seconds[1]) } : {}),
    ...(path ? { answerPath: path[1] } : {}),
  }
}

/** The exit code an errored Bash result reports (`Exit code 5`), when it does. */
export const exitCodeOf = (text: string): number | undefined => {
  const m = text.match(/^Exit code (\d+)/m)
  return m ? Number(m[1]) : undefined
}

export type TaskEnded = { taskId?: string; toolUseId?: string; status?: string; exitCode?: number; outputFile?: string }

/** A background task's notification, as the engine words it; null for any other prompt. */
export const parseTaskNotification = (text: string): TaskEnded | null => {
  if (!text.includes('<task-notification>')) return null
  const tag = (name: string) => text.match(new RegExp(`<${name}>([^<]*)</${name}>`))?.[1]?.trim() || undefined
  const code = (tag('summary') ?? '').match(/exit code (\d+)/i)
  return {
    taskId: tag('task-id'),
    toolUseId: tag('tool-use-id'),
    status: tag('status'),
    exitCode: code ? Number(code[1]) : undefined,
    outputFile: tag('output-file'),
  }
}

/** `1:05`, `12:40`, `1:02:03`. */
export const clock = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000))
  const mm = String(Math.floor(s / 60) % 60)
  const ss = String(s % 60).padStart(2, '0')
  return s >= 3600 ? `${Math.floor(s / 3600)}:${mm.padStart(2, '0')}:${ss}` : `${mm}:${ss}`
}

/** `Codex · GPT-6 Luna`, or what is known of it. */
export const whoOf = (tool: DelegateTool | null | undefined, name: string | null | undefined, m: Messages) =>
  tool ? `${TOOL_NAME[tool]} · ${name || '?'}` : name || m.delegate.notRecorded

/** What a finished run's exit code means, in the catalog's words. */
export const outcomeOf = (code: number | null | undefined, m: Messages) => (code === 0 ? m.delegate.answered : m.delegate.exitWord(code ?? null))

/** `950`, `12.3k`, `123k`, `1.2M`. */
export const compact = (n: number) => {
  const short = (x: number, unit: string) => `${x >= 100 ? Math.round(x) : x.toFixed(1).replace(/\.0$/, '')}${unit}`
  return n < 1000 ? String(Math.round(n)) : n < 999_500 ? short(n / 1000, 'k') : short(n / 1_000_000, 'M')
}

/** `$0.04`; a cost under a cent keeps its first figures. */
export const dollars = (usd: number) => `$${usd >= 0.01 || usd === 0 ? usd.toFixed(2) : usd.toPrecision(2)}`

/** `12.3k in · 1.1k out · $0.04`: the tokens when the CLI counted any, the cost only when it reported one; '' for none. */
export const usageText = (u: DelegateUsage | null | undefined, m: Messages) => {
  if (!u) return ''
  const hasTokens = (u.inputTokens ?? 0) > 0 || (u.outputTokens ?? 0) > 0
  return [
    ...(hasTokens && u.inputTokens !== null ? [m.delegate.tokensIn(compact(u.inputTokens))] : []),
    ...(hasTokens && u.outputTokens !== null ? [m.delegate.tokensOut(compact(u.outputTokens))] : []),
    ...(u.costUsd !== null ? [dollars(u.costUsd)] : []),
  ].join(' · ')
}

const withUsage = (text: string, u: DelegateUsage | null | undefined, m: Messages) => {
  const used = usageText(u, m)
  return used ? `${text} · ${used}` : text
}

/** The band's words for one run: the mark, and the line after the label. */
export const runLine = (r: DelegateRun, now: number, m: Messages): { mark: string; text: string } => {
  if (r.status === 'running') {
    const parts = [...(r.tool ? [TOOL_NAME[r.tool]] : []), ...(r.name ? [r.name] : []), clock(now - r.startedAt)]
    return { mark: '⏳', text: parts.join(' · ') + (r.taskId ? ` · ${m.delegate.inBackground}` : '') }
  }
  if (r.status === 'answered') {
    const ms = r.seconds !== undefined ? r.seconds * 1000 : (r.finishedAt ?? now) - r.startedAt
    return { mark: '✅', text: withUsage(`${clock(ms)} · ${m.delegate.answered}`, r.usage, m) }
  }
  if (r.status === 'failed') return { mark: '❌', text: withUsage(outcomeOf(r.exitCode, m), r.usage, m) }
  if (r.status === 'stopped') return { mark: '⏹', text: m.delegate.interrupted }
  return { mark: '⚠', text: m.delegate.lost }
}

const str = (v: unknown) => (typeof v === 'string' && v ? v : null)
const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : null)
const count = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : null)

/** The usage fields of a meta.json or a `list` entry (snake_case, as delegate.py writes them). */
export const usageOf = (o: Record<string, unknown>): DelegateUsage => ({
  inputTokens: count(o.input_tokens),
  outputTokens: count(o.output_tokens),
  cachedTokens: count(o.cached_tokens),
  costUsd: count(o.cost_usd),
})

/** A run folder's meta.json, read for its usage; null when it is unreadable or says nothing of it. */
export const parseMetaUsage = (text: string): DelegateUsage | null => {
  try {
    const raw = JSON.parse(text) as unknown
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null
    const u = usageOf(raw as Record<string, unknown>)
    return Object.values(u).some(v => v !== null) ? u : null
  } catch {
    return null
  }
}

/** `delegate.py list --format json`'s answer, checked; throws when it is no list. */
export const parseRecords = (stdout: string): DelegateRecord[] => {
  const raw = JSON.parse(stdout) as unknown
  if (!Array.isArray(raw)) throw new Error('delegate.py list did not answer a list')
  return raw.flatMap((x): DelegateRecord[] => {
    if (!x || typeof x !== 'object') return []
    const o = x as Record<string, unknown>
    const id = str(o.id)
    const path = str(o.path)
    if (!id || !path) return []
    return [
      {
        id,
        path,
        label: str(o.label) ?? '?',
        started: num(o.started),
        tool: TOOLS.find(t => t === o.tool) ?? null,
        model: str(o.model),
        name: str(o.name),
        seconds: num(o.seconds),
        exit: num(o.exit),
        answerPath: str(o.answer_path),
        answerBytes: num(o.answer_bytes),
        hasStderr: o.has_stderr === true,
        firstLine: str(o.first_line) ?? '',
        usage: usageOf(o),
      },
    ]
  })
}

/** One record's line after its time: `2:05 · answered · 12.3k in · 1.1k out`. */
export const recordResult = (r: DelegateRecord, m: Messages) => {
  if (r.exit === null) return m.delegate.noResult
  const base = r.exit === 0 && r.seconds !== null ? `${clock(r.seconds * 1000)} · ${m.delegate.answered}` : outcomeOf(r.exit, m)
  return withUsage(base, r.usage, m)
}

/**
 * The records pane's total line: the runs listed, their time, and per CLI the tokens (and cost) it
 * counted; a CLI that counted none is left out.
 */
export const recordsTotal = (records: readonly DelegateRecord[], m: Messages) => {
  const seconds = records.reduce((sum, r) => sum + (r.seconds ?? 0), 0)
  const perTool = TOOLS.flatMap(tool => {
    const mine = records.filter(r => r.tool === tool)
    const sum = (pick: (u: DelegateUsage) => number | null) => {
      const known = mine.map(r => pick(r.usage)).filter((v): v is number => v !== null)
      return known.length ? known.reduce((a, b) => a + b, 0) : null
    }
    const used = usageText({ inputTokens: sum(u => u.inputTokens), outputTokens: sum(u => u.outputTokens), cachedTokens: null, costUsd: sum(u => u.costUsd) }, m)
    return used ? [`${TOOL_NAME[tool]} ${used}`] : []
  })
  return m.delegate.recordsTotal(records.length, clock(seconds * 1000), perTool)
}

/**
 * The run folder a run in flight is, among the listed ones: its own once matched, else the earliest
 * one of its label started at or after it (a few seconds' leeway) that no other run has claimed.
 */
export const matchRecord = (run: DelegateRun, records: readonly DelegateRecord[], claimed: ReadonlySet<string>) => {
  if (run.folder) return records.find(r => r.path === run.folder)
  return records
    .filter(r => r.label === run.label && r.started !== null && r.started * 1000 >= run.startedAt - 5_000 && !claimed.has(r.path))
    .sort((a, b) => a.started! - b.started!)[0]
}

/** Answers longer than this go into the prompt box as a reference to their file. */
export const PASTE_MAX_CHARS = 20_000

/** What "into the prompt box" writes for an answer: the answer itself, or where to read it. */
export const pasteAnswer = (o: { label: string; who: string; path: string; text: string }, m: Messages) =>
  o.text.length <= PASTE_MAX_CHARS ? m.delegate.paste(o.label, o.who, o.path, o.text.trim()) : m.delegate.pasteRef(o.label, o.who, o.path)

files.hooks/sub5.ts:
/**
 * The Sub5 flow, as words: what the main agent is told when the Sub5 button is pressed (the brief is
 * in the catalogs, one per language), and the worker agent type it dispatches. The exact git parts
 * (base snapshot, applying, checking, cleaning) are bin/sub5.py's; the judgment (what to split, how to
 * rank, whether a result meets the bar) is the main agent's. Kept free of `$` so tests can read it.
 */
import type { Sub5KeepReason, Sub5Leftover } from '../types'
import { ago } from './codex'
import type { Locale, Messages } from './i18n'
import { shq } from './shell'

export const SUB5_AGENT = 'deckhand:sub5-worker'

export type Sub5Options = {
  /** At most this many items are dispatched at once. */
  max: number
  /** The workers' model and effort, as the agent type carries them. */
  model: string
  effort: string
  /** Absolute path of bin/sub5.py. */
  tool: string
  note?: string
  locale: Locale
  attribution: boolean
}

/** The prefix every sub5.py command of the brief starts with: the tool speaks the brief's language. */
export const sub5Run = (tool: string, locale: Locale) => `DECKHAND_LANG=${locale} python3 ${shq(tool)}`

export const sub5Prompt = (o: Sub5Options, m: Messages): string =>
  m.sub5.brief({
    max: o.max,
    model: o.model,
    effort: o.effort,
    run: sub5Run(o.tool, o.locale),
    note: o.note,
    languageName: m.languageName,
    attribution: o.attribution,
  })

export const WORKER_DESCRIPTION =
  'Parallel worker of the Sub5 flow: dispatched only by the main agent while it runs Sub5 (the user pressed the Sub5 button), to finish one assigned item in its own worktree. Not for ordinary delegation.'

export const workerPrompt = (languageName: string, attribution: boolean) =>
  [
    'You are a Sub5 worker, one of up to five parallel workers the main agent dispatched at once. You work in your own git worktree (the current directory). The assignment gives you RUN, ITEM, BASE (a commit SHA), the goal, the files you may change, the acceptance criteria and the verification commands.',
    '',
    'Rules',
    "1. Work only in your own worktree (the current directory). Do not read, write or operate on the main working tree, other worktrees or any remote; no push, no PR, no git config changes, never delete a branch or worktree (cleanup is the main agent's job).",
    '2. First step, never skipped: align the worktree to BASE.',
    '   BR=$(git branch --show-current); [ -n "$BR" ] || BR="sub5/<RUN>/<ITEM>"; git checkout -B "$BR" <BASE>',
    '   The worktree is new, so this is safe. Then check `git rev-parse HEAD` equals BASE; if not, stop and report RESULT: blocked.',
    "3. Do only the assigned item and change only the allowed files. If a file outside them must change, don't change it: explain why and what you suggest under NEEDS.",
    "4. Verify yourself: run the given verification commands; without any, the project's usual tests, type check, lint or build that cover your change. Record the results honestly. Fix failures until they pass; if you can't, say so, never claim a pass.",
    `5. Commit all changes on your branch (several commits are fine, project conventions${attribution ? ', no Co-Authored-By trailer and no "Generated with Claude Code" footer' : ''}). Before reporting, \`git status --porcelain\` must be empty.`,
    '6. Leave nothing behind: no files outside the worktree; temporary files go in `.sub5-tmp/` inside the worktree and are deleted before reporting, never committed; no background processes (dev servers, watchers): stop any you started and note it under NOTES.',
    '7. Never loosen a test, skip a check or change the acceptance criteria to make verification pass; put doubts under NEEDS.',
    '',
    `Report format (fixed field names; values in ${languageName})`,
    'RESULT: ready | blocked',
    'BRANCH: <git branch --show-current>',
    'WORKTREE: <pwd>',
    'HEAD: <git rev-parse HEAD>',
    'BASE: <the BASE you were given>',
    'FILES: <summary of git diff --stat BASE..HEAD>',
    'VERIFIED: <commands run and results>',
    'NOT_VERIFIED: <what was not verified and why; "none" if nothing>',
    'NEEDS: <what the main agent must decide or handle; "none" if nothing>',
    'NOTES: <for the integrator: risks, possible interactions with other items>',
    '',
    'When the main agent sends review comments: handle them point by point, verify again, commit again, and report again in the same format (decide RESULT afresh).',
  ].join('\n')

// ── Leftovers of interrupted runs: `sub5.py list` and `clean` ──

/**
 * The argv of `sub5.py list|clean --format json` in the session's folder. Never `--force`: Sub5 cleanup
 * never forces, so a dirty worktree or an unmerged branch stays for the person to deal with.
 */
export const leftoversArgv = (o: { python: string; tool: string; action: 'list' | 'clean'; cwd: string; locale: Locale }) => [
  o.python,
  o.tool,
  o.action,
  '--format',
  'json',
  '--cwd',
  o.cwd,
  '--lang',
  o.locale,
]

const KEEP_REASONS: readonly Sub5KeepReason[] = ['dirty', 'unmerged', 'recent', 'locked', 'current', 'busy']
const rec = (v: unknown): Record<string, unknown> => (v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : {})
const strOrNull = (v: unknown) => (typeof v === 'string' && v ? v : null)
const numOrNull = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : null)
const parseJson = (text: string): unknown => {
  try {
    return JSON.parse(text) as unknown
  } catch {
    return null
  }
}

/** The leftovers in `sub5.py list --format json`; null when the output is not that. */
export const parseLeftovers = (stdout: string): Sub5Leftover[] | null => {
  const o = rec(parseJson(stdout))
  if (!Array.isArray(o.entries)) return null
  return o.entries.map(raw => {
    const e = rec(raw)
    return {
      path: strOrNull(e.path),
      branch: strOrNull(e.branch),
      run: strOrNull(e.run),
      worktreeExists: e.worktree_exists === true,
      merged: e.merged === true,
      dirty: numOrNull(e.dirty),
      ageSeconds: numOrNull(e.age_seconds),
      removeWorktree: e.remove_worktree === true,
      deleteBranch: e.delete_branch === true,
      keep: (Array.isArray(e.keep) ? e.keep : []).filter((r): r is Sub5KeepReason => KEEP_REASONS.includes(r as Sub5KeepReason)),
    }
  })
}

/** What `sub5.py clean --format json` did, counted; null when the output is not that. */
export const parseCleaned = (stdout: string): { worktrees: number; branches: number; kept: number; failed: number } | null => {
  const o = rec(parseJson(stdout))
  const count = (v: unknown) => (Array.isArray(v) ? v.length : -1)
  const c = { worktrees: count(o.removed_worktrees), branches: count(o.deleted_branches), kept: count(o.kept), failed: count(o.failed) }
  return Object.values(c).some(n => n < 0) ? null : c
}

/** A leftover clean would act on: its worktree goes, its branch goes, or both. */
export const isActionable = (e: Sub5Leftover) => e.removeWorktree || e.deleteBranch

/** The line under a leftover in the pane: branch, age, merged or not, and what clean does with it. */
export const leftoverLine = (e: Sub5Leftover, m: Messages) => {
  const parts = [e.branch ?? m.sub5.cleanNoBranch]
  if (e.ageSeconds !== null) parts.push(ago(0, e.ageSeconds * 1000, m))
  parts.push(e.merged ? m.sub5.cleanMerged : m.sub5.cleanUnmerged)
  if (e.path && !e.worktreeExists) parts.push(m.sub5.cleanGone)
  if (e.dirty) parts.push(m.sub5.cleanDirty(e.dirty))
  if (!e.keep.length) parts.push(m.sub5.cleanWillRemove)
  else {
    if (e.removeWorktree) parts.push(m.sub5.cleanWorktreeOnly)
    parts.push(m.sub5.cleanKept(e.keep.map(r => m.sub5.reasons[r]).join(m.listSep)))
  }
  return parts.join(' · ')
}

/** The agent type the Sub5 brief dispatches: the workers' model and effort are the person's to set. */
export const workerSpec = (o: { model: string; effort: string; languageName: string; attribution: boolean }) => ({
  name: 'sub5-worker',
  description: WORKER_DESCRIPTION,
  prompt: workerPrompt(o.languageName, o.attribution),
  model: o.model,
  effort: o.effort,
  isolation: 'worktree' as const,
  background: true as const,
  // A worker neither fans out further nor moves between worktrees.
  disallowedTools: ['Agent', 'EnterWorktree', 'ExitWorktree'],
})

files.hooks/usage.ts:
/**
 * Pure logic of the usage readout and the model buttons: what each number is called, where it comes
 * from, and when a model switch is safe. No `$` here, so tests can call it.
 *
 * The numbers are the usage card's, from the same call the app makes: `GET /api/oauth/usage`. Its answer
 * has `five_hour` and `seven_day` ("Weekly · all models") as `{ utilization, resets_at }`, and a `limits`
 * list in which every `kind: "weekly_scoped"` entry names its model under `scope.model.display_name`
 * ("Weekly · Fable"). The card shows `Math.floor(utilization)`, so does this.
 *
 * The engine's own `rateLimits` (the last response's headers) is used for `5h` and nothing else: its
 * `seven_day` is the weekly window the answering model counts against, not a fixed one, so it is neither
 * "all models" nor "Fable" and never stands in for them.
 */

import type { Messages } from './i18n'

export type EngineLimit = { kind: string; percent: number; resetsAt?: string }

/** One window of the account's usage, as the usage API names it. */
export type AccountWindow = { key: string; label: string; percent: number; resetsAt?: string }

export type AccountLimits = {
  windows: AccountWindow[]
  fetchedAt: number
  /** `ok`, or why the account's usage could not be read (`no-credential`, `http-401`, ...). */
  status: string
  /** The answer as received, cut short, for `/usage-raw`. */
  raw?: string
}

export type Level = 'ok' | 'warn' | 'high' | 'unknown'

export type Segment = {
  /** `fiveHour`, `weekly`, `context`, or `scoped:<family>` for one model's weekly window. */
  id: string
  text: string
  percent: number | null
  level: Level
  resetsAt?: string
  /** A scoped window's model, as the card names it (`Fable`). */
  name?: string
}

const PERCENT_KEYS = ['utilization', 'percent_used', 'percentUsed', 'used_percentage', 'percent'] as const
const LABEL_KEYS = ['label', 'display_name', 'displayName', 'name', 'title'] as const
const NAME_KEYS = ['kind', 'type', 'key', 'id'] as const

const asObject = (value: unknown): Record<string, unknown> | null =>
  value !== null && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : null

const firstString = (o: Record<string, unknown>, keys: readonly string[]) => {
  for (const key of keys) if (typeof o[key] === 'string' && o[key] !== '') return o[key] as string
  return undefined
}

const firstNumber = (o: Record<string, unknown>, keys: readonly string[]) => {
  for (const key of keys) {
    const value = o[key]
    if (typeof value === 'number' && Number.isFinite(value)) return value
  }
  return undefined
}

const clampPercent = (n: number) => Math.min(100, Math.max(0, n))

/** The model or surface a `limits[]` entry is scoped to: `scope.model.display_name`, else `scope.surface.display_name`. */
const scopeName = (o: Record<string, unknown>) => {
  const scope = asObject(o.scope)
  for (const kind of ['model', 'surface']) {
    const name = asObject(scope?.[kind])?.display_name
    if (typeof name === 'string' && name.trim() !== '') return name.trim()
  }
  return undefined
}

/** The usage card's number: it floors, so 2.6% reads 2%. */
export const shownPercent = (percent: number) => Math.floor(percent)

/**
 * Finds the usage windows in whatever shape the usage API answers: an object per window under its own
 * key (`{ five_hour: { utilization, resets_at } }`), a `limits` list whose entries name their model under
 * `scope` (`{ kind: 'weekly_scoped', percent, scope: { model: { display_name: 'Fable' } } }`), or a list of
 * windows that name themselves (`[{ label, percentUsed }]`). A window is any object that carries a
 * percentage; null ones are skipped.
 */
export const parseAccountUsage = (json: unknown, now: number, status = 'ok', raw?: string): AccountLimits | null => {
  const windows: AccountWindow[] = []
  const seen = new Set<unknown>()
  const walk = (value: unknown, key: string, depth: number) => {
    if (depth > 3 || value === null || typeof value !== 'object' || seen.has(value)) return
    seen.add(value)
    if (Array.isArray(value)) {
      value.forEach((item, i) => {
        const o = asObject(item)
        walk(item, (o && firstString(o, NAME_KEYS)) || `${key}[${i}]`, depth + 1)
      })
      return
    }
    const o = value as Record<string, unknown>
    const percent = firstNumber(o, PERCENT_KEYS)
    if (percent !== undefined) {
      const scoped = scopeName(o)
      windows.push({
        key: scoped ? `${key}:${scoped}` : key,
        label: firstString(o, LABEL_KEYS) ?? scoped ?? key,
        percent: clampPercent(percent),
        resetsAt: firstString(o, ['resets_at', 'resetsAt']),
      })
      return
    }
    for (const [k, v] of Object.entries(o)) walk(v, k, depth + 1)
  }
  walk(json, '', 0)
  return windows.length > 0 ? { windows, fetchedAt: now, status, raw } : null
}

/** The model families a weekly window can be scoped to, and their two-letter readout. */
export const SCOPED_FAMILIES: Readonly<Record<string, string>> = { fable: 'fb', opus: 'op', sonnet: 'sn', haiku: 'hk' }

/**
 * The model family a window is scoped to, or null: `weekly_scoped:Fable 5.1`, `seven_day_sonnet`,
 * or a label like "Weekly · Fable". A surface-scoped window (Claude Design) is no model's.
 */
export const scopedFamily = (w: AccountWindow): string | null => {
  const named = w.key.includes(':') ? w.key.slice(w.key.indexOf(':') + 1) : ''
  const plain = w.key.match(/^seven_day_([a-z]+)$/)?.[1] ?? ''
  for (const text of [named, plain, w.label]) {
    const hit = Object.keys(SCOPED_FAMILIES).find(f => new RegExp(`\\b${f}\\b`, 'i').test(text))
    if (hit) return hit
  }
  return null
}
const isWeeklyAll = (w: AccountWindow) =>
  scopedFamily(w) === null && (w.key === 'seven_day' || (/weekly|7.?day|每週/i.test(w.label) && /all models|所有模型/i.test(w.label)))
const isFiveHour = (w: AccountWindow) =>
  w.key === 'five_hour' || /(^|\W)(5|five)[- ]?hour|current session|工作階段/i.test(w.label)

/** A reading older than this is not shown as current. */
export const ACCOUNT_MAX_AGE_MS = 30 * 60_000

const levelOf = (percent: number | null, warnAt: number): Level =>
  percent === null ? 'unknown' : percent >= 95 ? 'high' : percent >= warnAt ? 'warn' : 'ok'

export type UsageInput = {
  engine: readonly EngineLimit[]
  account: AccountLimits | null
  contextPercent: number | null
  now: number
  warnAt: number
  /** Scoped families seen in earlier readings: they read `–` while the account can't be read. */
  knownScoped?: readonly string[]
}

const capitalized = (f: string) => f.charAt(0).toUpperCase() + f.slice(1)

/**
 * The readout, in order: `5h`, each model's weekly window (`fb` for Fable), `7d` (Weekly · all
 * models), `ctx`, as the usage card shows them. The weekly ones come from the account's usage alone
 * and read `–` when it cannot be read (a wrong number is worse than none); `5h` falls back to the
 * engine's `five_hour`, which is that same window. The context window is left out until known.
 */
export const usageSegments = (input: UsageInput): Segment[] => {
  const isFresh = input.account !== null && input.account.status === 'ok' && input.now - input.account.fetchedAt <= ACCOUNT_MAX_AGE_MS
  const windows = isFresh ? input.account!.windows : []
  const engineFive = input.engine.find(l => l.kind === 'five_hour')

  const five = windows.find(isFiveHour)
  const weekly = windows.find(isWeeklyAll)
  const scoped = new Map<string, AccountWindow>()
  for (const w of windows) {
    const f = scopedFamily(w)
    if (f && !scoped.has(f)) scoped.set(f, w)
  }
  const families = [...new Set([...scoped.keys(), ...(input.knownScoped ?? [])])].filter(f => f in SCOPED_FAMILIES)

  const pick = (id: string, label: string, percent: number | null | undefined, resetsAt: string | undefined, name?: string): Segment => {
    const value = percent ?? null
    return {
      id,
      text: `${label} ${value === null ? '–' : `${shownPercent(value)}%`}`,
      percent: value,
      level: levelOf(value, input.warnAt),
      resetsAt,
      ...(name ? { name } : {}),
    }
  }

  const segments = [
    pick('fiveHour', '5h', five?.percent ?? engineFive?.percent, five?.resetsAt ?? engineFive?.resetsAt),
    ...families.map(f => pick(`scoped:${f}`, SCOPED_FAMILIES[f]!, scoped.get(f)?.percent, scoped.get(f)?.resetsAt, capitalized(f))),
    pick('weekly', '7d', weekly?.percent, weekly?.resetsAt),
  ]
  if (input.contextPercent !== null) segments.push(pick('context', 'ctx', input.contextPercent, undefined))
  return segments
}

/** The account's windows and the engine's, as they are, for `/usage-raw`. */
export const describeSources = (engine: readonly EngineLimit[], account: AccountLimits | null, now: number, m: Messages) => {
  const lines = [m.usage.engineHeader]
  lines.push(...(engine.length ? engine.map(l => `  ${l.kind}  ${l.percent}%${l.resetsAt ? m.usage.resetsAt(l.resetsAt) : ''}`) : [m.usage.noReading]))
  lines.push('', m.usage.accountHeader(account ? account.status : m.usage.notRead, account ? m.usage.secondsAgo(Math.round((now - account.fetchedAt) / 1000)) : ''))
  if (account && account.status === 'ok') {
    lines.push(
      ...account.windows.map(
        w => `  ${w.key}  「${w.label}」  ${w.percent}%${m.usage.cardShows(shownPercent(w.percent))}${w.resetsAt ? m.usage.resetsAt(w.resetsAt) : ''}`,
      ),
    )
    if (account.raw) lines.push('', `${m.usage.raw}${account.raw}`)
  }
  return lines
}

// ── models ─────────────────────────────────────────────────────────────────

export type Family = 'opus' | 'fable' | 'sonnet' | 'haiku'

export const MODEL_BUTTONS: ReadonlyArray<{ key: string; family: Family; name: string }> = [
  { key: 'O', family: 'opus', name: 'Opus' },
  { key: 'F', family: 'fable', name: 'Fable' },
  { key: 'S', family: 'sonnet', name: 'Sonnet' },
  { key: 'H', family: 'haiku', name: 'Haiku' },
]

/** Which button a model id belongs to (`claude-sonnet-5-5`, `sonnet[1m]`, ...); null for a model with none. */
export const modelFamily = (model: string): Family | null => {
  const m = model.toLowerCase()
  return MODEL_BUTTONS.find(b => m.includes(b.family))?.family ?? null
}

/**
 * The desktop app's model menu knows a model only by its full id (`claude-opus-5-5`): a `/model opus`
 * still switches the engine, but the menu then reads "unsupported model". These ids stand in until the
 * engine has named the current ones (`learnModelId`); what it names wins.
 */
export const DEFAULT_MODEL_IDS: Readonly<Record<Family, string>> = {
  opus: 'claude-opus-5-5',
  fable: 'claude-fable-5-1',
  sonnet: 'claude-sonnet-5-5',
  haiku: 'claude-haiku-4-5-20251001',
}

/**
 * A full model id the engine named, with its family: `claude-opus-5-5[1m]` as `session.model()`
 * reports it, or `Set model to \`opus (claude-opus-5-5)\`` as `/model` answers. Null for anything else.
 */
export const learnModelId = (text: string): { family: Family; id: string } | null => {
  const id = (text.match(/\((claude-[a-z0-9.-]{3,60})(?:\[[^\]]{1,10}\])?\)/i)?.[1] ?? text.trim().match(/^(claude-[a-z0-9.-]{3,60})(?:\[[^\]]{1,10}\])?$/i)?.[1] ?? '').toLowerCase()
  const family = id ? modelFamily(id) : null
  return family ? { family, id } : null
}

/** What the desktop button sends: the full id for the alias's family, the alias's `[1m]` kept. */
export const desktopModelArg = (alias: string, known: Partial<Record<Family, string>>) => {
  const family = modelFamily(alias)
  if (!family) return alias
  const suffix = alias.match(/\[[^\]]+\]$/)?.[0] ?? ''
  return `${known[family] ?? DEFAULT_MODEL_IDS[family]}${suffix}`
}

export const EFFORT_LEVELS = ['low', 'medium', 'high', 'xhigh', 'max'] as const

export const effortLevel = (value: unknown): string | null =>
  typeof value === 'string' && (EFFORT_LEVELS as readonly string[]).includes(value) ? value : null

/** Haiku's window is far smaller than the others': a long conversation does not fit in it. */
export const HAIKU_SAFE_TOKENS = 150_000

export type SwitchPlan =
  | { ok: true; alias: string; keepEffort: boolean }
  | { ok: false; reason: string }

/**
 * What a click on a model button does. The alias is the family name (`/model opus` takes the latest Opus),
 * with `[1m]` kept when the session runs on the 1M-token window, so that a switch never shrinks it.
 * Haiku takes no effort setting, so none is carried over to it.
 */
export const planSwitch = (current: string, target: Family, contextTokens: number | null, m: Messages): SwitchPlan => {
  const name = MODEL_BUTTONS.find(b => b.family === target)!.name
  if (modelFamily(current) === target) return { ok: false, reason: m.model.already(name) }
  if (target === 'haiku' && contextTokens !== null && contextTokens > HAIKU_SAFE_TOKENS) {
    return {
      ok: false,
      reason: m.model.haikuTooLong(Math.round(contextTokens / 1000)),
    }
  }
  const keepsLongWindow = /\[1m\]/i.test(current) && target !== 'haiku'
  return { ok: true, alias: keepsLongWindow ? `${target}[1m]` : target, keepEffort: target !== 'haiku' }
}

