/**
 * Pure logic of the deploy watch: target parsing, turning gh / HTTP answers
 * into a signature and summary, and the stop rules (identical results, stall
 * time, flapping pages, a ceiling) with their backoff. The engine calls live
 * in register.tsx.
 */
import { changingParts } from './fingerprint'
import type { Messages } from './i18n'
import type { Watch, WatchKind } from '../types'

export type WatchSettings = {
  /** First interval between checks. */
  baseMs: number
  /** Identical results in a row that make a watch a candidate for stopping. */
  limit: number
  /** ...and the watch stops only once its status has also stood still this long (0: the count alone). */
  stallMs: number
}

/**
 * `followUp`: a target to watch next once this one is done (a merged PR's CI).
 * `baseline`: what a URL watch compares later pages with. `stop`: ends the watch at once, with its reason.
 */
export type CheckResult = {
  signature: string
  summary: string
  isDone: boolean
  followUp?: string
  baseline?: string
  stop?: string
}

export type Target = { kind: WatchKind; target: string; repo?: string }

/**
 * Reads `#128`, `128`, `pr:128`, `run:123`, `sha:<commit>`, a GitHub PR / run URL, or any http(s) URL.
 * A short form may name its repo first (`owner/repo#128`, `owner/repo run:123`, `owner/repo sha:…`):
 * without one, gh reads the repo from the watch's working directory.
 */
export const parseTarget = (raw: string): Target | null => {
  let text = raw.trim()
  const owned = text.match(/^([\w.-]{1,100}\/[\w.-]{1,100})[\s#:@]+(.+)$/)
  if (owned && !/^https?:\/\//.test(text)) {
    const rest = parseTarget(owned[2]!.replace(/^[\s#:@]+/, m => (m.includes('#') ? '#' : '')))
    return rest && rest.kind !== 'url' && !rest.repo ? { ...rest, repo: owned[1]! } : null
  }
  const pr = text.match(/github\.com\/([^/\s]+\/[^/\s]+)\/pull\/(\d+)/)
  if (pr) return { kind: 'pr', target: pr[2]!, repo: pr[1]! }
  const run = text.match(/github\.com\/([^/\s]+\/[^/\s]+)\/actions\/runs\/(\d+)/)
  if (run) return { kind: 'run', target: run[2]!, repo: run[1]! }
  if (/^https?:\/\//.test(text)) return { kind: 'url', target: text }
  const prNumber = text.match(/^(?:pr[:#\s]*)?#?(\d+)$/i)
  if (prNumber) return { kind: 'pr', target: prNumber[1]! }
  const runId = text.match(/^run[:#\s]*(\d+)$/i)
  if (runId) return { kind: 'run', target: runId[1]! }
  const sha = text.match(/^(?:sha|commit)[:\s]*([0-9a-f]{7,40})$/i)
  if (sha) return { kind: 'run', target: `sha:${sha[1]!}` }
  return null
}

export const labelOf = (t: Target) =>
  t.kind === 'pr'
    ? `PR #${t.target}`
    : t.kind === 'run'
      ? t.target.startsWith('sha:')
        ? `CI @${t.target.slice(4, 11)}`
        : `Run ${t.target}`
      : t.target.replace(/^https?:\/\//, '').slice(0, 48)

/** gh could not read a repo from the working directory: the watch needs `--repo`. */
export const isNoRepo = (message: string) => /determine base repo|not a git repository|不是一個 git 版本庫|no git remotes/i.test(message)

/** The gh argv (without `gh` and `--repo`) for one check of a PR or run watch. */
export const ghArgs = (w: Pick<Watch, 'kind' | 'target'>): string[] =>
  w.kind === 'pr'
    ? ['pr', 'view', w.target, '--json', 'number,title,state,mergeStateStatus,statusCheckRollup,mergeCommit']
    : w.target.startsWith('sha:')
      ? ['run', 'list', '--commit', w.target.slice(4), '--limit', '30', '--json', 'databaseId,status,conclusion,workflowName']
      : ['run', 'view', w.target, '--json', 'databaseId,status,conclusion,workflowName']

type CheckItem = { status?: string; conclusion?: string; state?: string }

export const tally = (items: readonly CheckItem[]) => {
  let pass = 0
  let fail = 0
  let pending = 0
  for (const item of items) {
    const verdict = (item.conclusion || item.state || '').toUpperCase()
    const isComplete = item.status
      ? item.status.toUpperCase() === 'COMPLETED'
      : verdict !== '' && verdict !== 'PENDING' && verdict !== 'EXPECTED'
    if (!isComplete) pending += 1
    else if (['SUCCESS', 'NEUTRAL', 'SKIPPED'].includes(verdict)) pass += 1
    else fail += 1
  }
  return { pass, fail, pending }
}

export type PrView = {
  state: string
  mergeStateStatus: string
  statusCheckRollup: CheckItem[] | null
  mergeCommit: { oid: string } | null
}

export const prResult = (pr: PrView, m: Messages): CheckResult => {
  const { pass, fail, pending } = tally(pr.statusCheckRollup ?? [])
  const checks = pass + fail + pending > 0 ? `checks ✓${pass} ✗${fail} …${pending}` : 'no checks'
  const isMerged = pr.state === 'MERGED'
  const merge = isMerged && pr.mergeCommit ? m.watch.merged(pr.mergeCommit.oid.slice(0, 7)) : ''
  return {
    signature: `${pr.state}|${pr.mergeStateStatus}|${pass}/${fail}/${pending}`,
    summary: `${pr.state} · ${checks} · ${pr.mergeStateStatus}${merge}`,
    isDone: isMerged || pr.state === 'CLOSED' || (pending === 0 && fail > 0),
    followUp: isMerged && pr.mergeCommit ? `sha:${pr.mergeCommit.oid}` : undefined,
  }
}

export type RunItem = { databaseId?: number; status: string; conclusion: string; workflowName?: string }

/** A job's outcome that is not a pass, as `gh run view --json jobs` reports it. */
const isFailedJob = (conclusion: string) => ['failure', 'timed_out', 'cancelled', 'startup_failure'].includes(conclusion.toLowerCase())

/**
 * The jobs that failed in runs GitHub counts as passed: a job with `continue-on-error` fails without
 * failing its run, so a run's conclusion alone would read "all passed".
 */
export const failedJobs = (jobs: readonly { name?: string; conclusion?: string | null }[]) =>
  jobs.filter(j => j.conclusion && isFailedJob(j.conclusion)).map(j => j.name ?? 'job')

/** A finished run result that also names the jobs that were allowed to fail and did. */
export const withAllowedFailures = (result: CheckResult, names: readonly string[], m: Messages): CheckResult =>
  names.length === 0 ? result : { ...result, summary: `${result.summary} · ${m.watch.allowedFailures(names.length, names.join(', '))}` }

export const runResult = (runs: readonly RunItem[], m: Messages): CheckResult => {
  if (runs.length === 0) return { signature: 'none', summary: m.watch.noRuns, isDone: false }
  const done = runs.filter(r => r.status.toLowerCase() === 'completed')
  const failed = done.filter(r => !['success', 'skipped', 'neutral'].includes(r.conclusion.toLowerCase()))
  const states = runs.map(r => `${r.workflowName ?? 'run'}:${r.status === 'completed' ? r.conclusion : r.status}`)
  return {
    signature: [...states].sort().join(','),
    summary: m.watch.runs(done.length, runs.length, failed.map(r => r.workflowName ?? 'run').join(', '), done.length === runs.length),
    isDone: done.length === runs.length,
  }
}

// ── URL watch ──────────────────────────────────────────────────────────────

/** Checks in a row that all differ from the one before: no deploy looks like that. */
const FLAPPING_RUN = 6

const shortPrint = (fingerprint: string) => fingerprint.replace(/^[a-z]+:/, '').slice(0, 8)

/**
 * One check of a URL. With `expect`, done when that text shows up on a healthy page. Without it,
 * done when the page's fingerprint (see fingerprint.ts) differs from the first healthy one and the
 * next check sees the same new fingerprint: one odd response from one node is not a deploy. A page
 * whose fingerprint differs on every check has random content, and no answer can be read from it.
 */
export const urlResult = (
  w: Pick<Watch, 'expect' | 'baseline' | 'signature' | 'seen'>,
  status: number,
  fingerprint: string,
  body: string,
  m: Messages,
): CheckResult => {
  const isUp = status >= 200 && status < 400
  if (w.expect) {
    const isLive = isUp && body.includes(w.expect)
    return {
      signature: `${status}|${isLive ? 'live' : 'waiting'}`,
      summary: m.watch.expect(status, isLive, w.expect),
      isDone: isLive,
    }
  }
  if (!isUp) return { signature: `http-${status}`, summary: m.watch.down(status), isDone: false }

  const signature = `${status}|${fingerprint}`
  const baseline = w.baseline ?? signature
  const recent = [...(w.seen ?? []), signature].slice(-FLAPPING_RUN)
  if (recent.length === FLAPPING_RUN && recent.every((s, i) => i === 0 || s !== recent[i - 1])) {
    const parts = changingParts(recent).map(p => m.watch.parts[p] ?? p)
    return {
      signature,
      baseline,
      isDone: false,
      summary: m.watch.flapping(status),
      stop: m.watch.flappingStop(parts.join(m.listSep)),
    }
  }
  if (signature === baseline) {
    return { signature, baseline, isDone: false, summary: m.watch.same(status, shortPrint(fingerprint)) }
  }
  const isConfirmed = w.signature === signature
  return {
    signature,
    baseline,
    isDone: isConfirmed,
    summary: isConfirmed
      ? m.watch.confirmed(status, shortPrint(fingerprint))
      : m.watch.changed(status),
  }
}

export const errorResult = (message: string, m: Messages): CheckResult => ({
  signature: `error:${message}`,
  summary: m.watch.checkFailed(message),
  isDone: false,
})

// ── stopping ───────────────────────────────────────────────────────────────

/** A watch that has never finished is stopped here whatever else happens. */
export const MAX_CHECKS = 120
const MAX_INTERVAL_MS = 300_000

/**
 * Applies one check result to a watch. A watch stops when it is done, when the page says so
 * (`stop`), when `limit` identical results in a row have also stood still for `stallMs`, or at
 * MAX_CHECKS. The stall time keeps a long single CI step from looking like a hang; the count
 * keeps a PR nobody is reviewing from being watched forever.
 */
export const advance = (w: Watch, r: CheckResult, now: number, s: WatchSettings, m: Messages): Watch => {
  const isSame = w.checks > 0 && r.signature === w.signature
  const unchanged = isSame ? w.unchanged + 1 : 0
  const changedAt = isSame ? (w.changedAt ?? now) : now
  const next: Watch = {
    ...w,
    summary: r.summary,
    signature: r.signature,
    unchanged,
    changedAt,
    seen: [...(w.seen ?? []), r.signature].slice(-8),
    baseline: r.baseline ?? w.baseline,
    checks: w.checks + 1,
  }
  if (r.isDone) return { ...next, status: 'done', reason: r.summary }
  if (r.stop) return { ...next, status: 'stopped', reason: r.stop }
  const stalledMs = now - changedAt
  if (unchanged + 1 >= s.limit && stalledMs >= s.stallMs) {
    const stall = s.stallMs > 0 ? m.watch.stall(Math.floor(stalledMs / 60_000)) : ''
    return { ...next, status: 'stopped', reason: m.watch.stoppedSame(unchanged + 1, stall, r.summary) }
  }
  if (next.checks >= MAX_CHECKS) {
    return { ...next, status: 'stopped', reason: m.watch.stoppedMax(MAX_CHECKS, r.summary) }
  }
  const intervalMs = Math.min(s.baseMs * 2 ** Math.min(unchanged, 4), Math.max(s.baseMs, MAX_INTERVAL_MS))
  return { ...next, intervalMs, nextAt: now + intervalMs }
}

export const newWatch = (
  t: Target,
  id: string,
  cwd: string,
  now: number,
  s: WatchSettings,
  extra: Pick<Watch, 'expect' | 'startedBy'>,
  m: Messages,
): Watch => ({
  id,
  ...t,
  ...extra,
  cwd,
  label: labelOf(t),
  summary: m.watch.first,
  signature: '',
  unchanged: 0,
  changedAt: now,
  seen: [],
  checks: 0,
  intervalMs: s.baseMs,
  nextAt: now,
  status: 'watching',
})

export const describeWatch = (w: Watch, m: Messages) => {
  const state = w.status === 'watching' ? m.watch.watching(w.checks, w.unchanged) : w.status === 'done' ? m.watch.done : m.watch.stopped
  return `${w.label}｜${state}｜${w.reason ?? w.summary}`
}

export const notice = (w: Watch, m: Messages) => {
  const head = w.status === 'done' ? m.watch.headDone : m.watch.headStopped
  const nextStep = w.status === 'stopped' ? m.watch.nextStopped : m.watch.nextDone
  return {
    toast: `${head}｜${w.label}：${w.reason ?? w.summary}`,
    note: `${head}：${w.label}（${w.kind} ${w.target}）→ ${w.reason ?? w.summary}。${nextStep}`,
  }
}

files.types/index.d.ts:
export type WatchKind = 'pr' | 'run' | 'url'

export type WatchStatus = 'watching' | 'done' | 'stopped'

/** One deploy / PR / CI / site watch, polled locally without model tokens. */
export type Watch = {
  id: string
  kind: WatchKind
  /** PR number, Actions run id, or URL. */
  target: string
  /** owner/repo for `gh --repo`; absent means the session's repo. */
  repo?: string
  /** For a URL watch: text whose appearance means the new version is live. */
  expect?: string
  cwd: string
  label: string
  /** Latest human-readable state. */
  summary: string
  /** What "no change" is measured against. */
  signature: string
  /** Rechecks that found the same signature as the check before (0 right after a change). */
  unchanged: number
  /** When the signature last changed; a watch stops only after it has stood still long enough. */
  changedAt?: number
  /** The signatures of the last checks, newest last: tells a page that flaps from one that deployed. */
  seen?: string[]
  /** URL watch without `expect`: the first healthy signature; a different one, seen twice, means a deploy. */
  baseline?: string
  checks: number
  intervalMs: number
  nextAt: number
  status: WatchStatus
  reason?: string
  startedBy: 'user' | 'model'
}

/** A user-facing Codex thread, read from ~/.codex. */
export type CodexThread = {
  id: string
  name: string
  cwd: string
  updatedAt: number
  lastUser: string
  lastAssistant: string
}

/** A rate-limit window as the engine reports it for the last API response. */
export type EngineLimit = { kind: string; percent: number; resetsAt?: string }

/** One window of the account's usage (what the app's usage card shows). */
export type AccountWindow = { key: string; label: string; percent: number; resetsAt?: string }

export type AccountLimits = {
  windows: AccountWindow[]
  fetchedAt: number
  /** `ok`, or why the account's usage could not be read. */
  status: string
  raw?: string
}

export type Locale = 'en' | 'zh-TW' | 'zh-CN' | 'ja' | 'ko'

export type DelegateTool = 'codex' | 'agent' | 'agy'

/** One delegate button: which CLI, which model, at which effort. */
export type DelegateTarget = {
  /** The button's label, 1 to 6 letters or digits, case kept (`cL`). */
  key: string
  enabled: boolean
  tool: DelegateTool
  /** The model id as the CLI takes it (`gpt-6-luna`, `grok-4.7-high`). */
  model: string
  effort: string
  /** The model as people say it, for the tooltip and the brief. */
  name: string
}

/** A tool that hands one kind of work to a delegate: off until the person turns it on. */
export type Assist = { enabled: boolean; slot: number }

/** Which part of the ⚙ pane shows, which delegate is open for editing, whether reset waits for a confirm. */
export type SettingsView = { tab: 'general' | 'delegates' | 'assist' | 'sub5' | 'advanced'; editing: number; isResetArmed: boolean }

/**
 * The settings file group of the Advanced tab: the path typed, and an export or import that waits
 * for a confirm (an export over a file that exists; an import with what it would change).
 */
export type SettingsFileView = {
  path: string
  armed: 'export' | 'import' | null
  /** The imported settings, normalized against the current ones; applied on the confirm press. */
  pending: DeckhandSettings | null
  changes: number
}

/** Why `sub5.py clean` keeps a leftover. */
export type Sub5KeepReason = 'dirty' | 'unmerged' | 'recent' | 'locked' | 'current' | 'busy'

/** One worktree or branch an interrupted Sub5 run left behind, as `sub5.py list --format json` reports it. */
export type Sub5Leftover = {
  path: string | null
  branch: string | null
  run: string | null
  worktreeExists: boolean
  merged: boolean
  dirty: number | null
  ageSeconds: number | null
  removeWorktree: boolean
  deleteBranch: boolean
  keep: Sub5KeepReason[]
}

/** The Sub5 leftovers pane: the last list, and a clean that waits for its confirm press. */
export type Sub5Leftovers = {
  status: 'idle' | 'loading' | 'done' | 'error'
  entries: Sub5Leftover[]
  error: string | null
  isArmed: boolean
  isCleaning: boolean
}

/** The person's settings, edited in the ⚙ pane and kept in `$.store`. */
export type DeckhandSettings = {
  version: 3
  /** `auto` follows Claude Code's own `language` setting. */
  language: 'auto' | Locale
  show: { usage: boolean; models: boolean; sub5: boolean; delegates: boolean; recap: boolean }
  delegates: DelegateTarget[]
  sub5: { max: number; model: string; effort: string }
  /** Empty means: find it (PATH, then the usual install places). */
  paths: { codexHome: string; codexBin: string; agentBin: string; agyBin: string }
  guards: { attribution: boolean; polling: boolean; repeatLimit: number }
  watch: { pollSeconds: number; stallMinutes: number }
  usage: { warnPercent: number }
  /** The translate tool: on or off, and the delegate slot (0 to 4) it hands the text to. */
  translate: Assist
  /** The search tool: on or off, and the delegate slot (0 to 4) that searches the web. */
  search: Assist
}

/** What the recap pane shows. */
export type RecapState = { status: 'idle' | 'working' | 'done' | 'error'; text: string; at: number }

export type DelegateRunStatus = 'running' | 'answered' | 'failed' | 'stopped' | 'lost'

/** What a run used, as its CLI printed it (meta.json); null where it did not say. No price is ever computed. */
export type DelegateUsage = {
  inputTokens: number | null
  outputTokens: number | null
  cachedTokens: number | null
  /** Only when the CLI itself reports a cost; none does today. */
  costUsd: number | null
}

/** A `delegate.py run` Bash call, as the band shows it while it runs and for a while after. */
export type DelegateRun = {
  /** The Bash call's id. */
  id: string
  label: string
  tool?: DelegateTool
  name?: string
  startedAt: number
  /** delegate.py's --timeout (its default when absent): a run with no word long past it is lost. */
  timeoutMin: number
  status: DelegateRunStatus
  /** delegate.py's exit code: 0 answered, 2 refused, 3 CLI not found, 4 timed out, 5 failed. */
  exitCode?: number
  /** How long the delegated model took, as delegate.py said. */
  seconds?: number
  finishedAt?: number
  answerPath?: string
  /** The background task the call became: its notification ends the run. */
  taskId?: string
  /** The run folder, once `delegate.py list` matched it. */
  folder?: string
  /** Read from the run folder's meta.json once the run ended. */
  usage?: DelegateUsage
}

/** One run folder, as `delegate.py list` reports it; null where its meta.json does not say. */
export type DelegateRecord = {
  id: string
  path: string
  label: string
  /** Epoch seconds. */
  started: number | null
  tool: DelegateTool | null
  model: string | null
  name: string | null
  seconds: number | null
  exit: number | null
  answerPath: string | null
  answerBytes: number | null
  hasStderr: boolean
  firstLine: string
  usage: DelegateUsage
}

/** The answer the records pane has open. */
export type DelegateAnswer = { path: string; label: string; who: string; text: string }

declare module 'claude-code' {
  interface PluginState {
    'deckhand': {
      watches: Watch[]
      isBandHidden: boolean
      codexThreads: CodexThread[]
      codexError: string | null
      isCodexLoading: boolean
      codexAllProjects: boolean
      engineLimits: EngineLimit[]
      accountLimits: AccountLimits | null
      contextPercent: number | null
      contextTokens: number | null
      /** The main loop's model, as `/model` shows it: which button is lit. */
      model: string
      /** The effort of the last finished turn: what a model switch keeps. */
      effort: string | null
      /** The person's settings; null until the session has loaded them. */
      settings: DeckhandSettings | null
      /** The language the band, the panes and the briefs speak. */
      locale: Locale
      /** The recap pane's content. */
      recap: RecapState
      settingsView: SettingsView
      isSettingsOpen: boolean
      settingsFile: SettingsFileView
      /** What `sub5.py list` last found: the leftovers pane and the Sub5 tab's count. */
      sub5Leftovers: Sub5Leftovers
      /** Where each delegate CLI was found: a path, null when missing, absent while unchecked. */
      bins: Partial<Record<DelegateTool, string | null>>
      /** Model families whose weekly window the account has shown: they read – while unreadable. */
      knownScoped: string[]
      /** Delegate runs in flight and just finished: the band's progress rows. Never the brief. */
      delegateRuns: DelegateRun[]
      /** Written every second while a run is in flight: what makes its elapsed time tick. */
      delegateTick: number
      /** The records pane: the run folders of the last 3 days, and the answer it has open. */
      delegateRecords: DelegateRecord[]
      delegateRecordsError: string | null
      isDelegateRecordsLoading: boolean
      delegateAnswer: DelegateAnswer | null
    }
  }
}
